s=s.replace("'files':{}}\n        for key in ('.cells.jsonl.gz','.render.json'):", "'files':{},'storage_mode':header['storage_mode'],'retained_cell_payload':not render_only}\n        if render_only:\n            stats['compiled_header']=header;stats['occupancy_certificate_sha256']=gzip_sha\n            stats['replay_contract']=render_only_retention.preserve_replay_sources(a,HERE,asset_key,master_path,source_path,catalog_path,rules_path,{\n                'core':a.core.__file__,'engine':__file__,'adapter':a.__file__,'connected_constraints':connected_constraints.__file__,\n                'polygon_crop_guard':polygon_crop_guard.__file__,'retention':render_only_retention.__file__,\n                'render_data':sys.modules[make_render_data.__module__].__file__,'mesh':sys.modules['mesh'].__file__,\n                'rules':rules_path,'catalog':catalog_path})\n        for key in active_file_keys:")
